+fn trailmix_q_width_at_step(wq: usize, step: usize) -> usize {
+    let capped = trailmix_q_width(wq);
+    let giveback_width = || {
+        std::env::var("TRAILMIX_Q_GIVEBACK_WIDTH")
+            .ok()
+            .and_then(|s| s.parse::<usize>().ok())
+            .unwrap_or(wq)
+            .min(wq.max(1))
+    };
+    if std::env::var("TRAILMIX_Q_GIVEBACK_STEPS")
+        .ok()
+        .is_some_and(|steps| {
+            steps
+                .split(',')
+                .filter_map(|s| s.trim().parse::<usize>().ok())
+                .any(|candidate| candidate == step)
+        })
+    {
+        return capped.max(giveback_width());
+    }
+    let Some(giveback_step) = std::env::var("TRAILMIX_Q_GIVEBACK_STEP")
+        .ok()
+        .and_then(|s| s.parse::<usize>().ok())
+    else {
+        return capped;
+    };
+    if giveback_step != step {
+        return capped;
+    }
+    capped.max(giveback_width())
+}

